<!DOCTYPE html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Администрирование — ARENA X</title>
<style>:root{color-scheme:dark;--bg:#101114;--panel:#191b20;--line:#2a2d34;--text:#f4f5f7;--muted:#969ba6;--accent:#d8ff45}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 Inter,system-ui,sans-serif}.shell{max-width:1100px;margin:auto;padding:0 24px}header{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{font-size:21px;font-weight:900;letter-spacing:.12em;text-decoration:none;color:white}.brand span{color:var(--accent)}a{color:inherit;text-decoration:none}.muted{color:var(--muted)}h1{font-size:38px;letter-spacing:-.04em;margin:40px 0 5px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0}.stat,.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px}.stat strong{font-size:30px;display:block}.stat span{color:var(--muted);font-size:13px}.panel{margin-bottom:16px}.panel h2{margin:0 0 12px}.line{padding:12px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:15px}.line:first-of-type{border-top:0}.small{color:var(--muted);font-size:13px}@media(max-width:700px){.shell{padding:0 16px}.stats{grid-template-columns:1fr 1fr}}
</style></head><body><div class="shell"><header><a class="brand" href="/">ARENA <span>X</span></a><a class="muted" href="{{ route('dashboard') }}">Личный кабинет</a></header><main><h1>Администрирование</h1><p class="muted">Обзор пользователей, турниров и заявок платформы.</p>
<section class="stats"><div class="stat"><strong>{{ $usersCount }}</strong><span>Пользователи</span></div><div class="stat"><strong>{{ $teamsCount }}</strong><span>Команды</span></div><div class="stat"><strong>{{ $tournamentsCount }}</strong><span>Турниры</span></div><div class="stat"><strong>{{ $pendingCount }}</strong><span>Заявки на рассмотрении</span></div></section>
<section class="panel"><h2>Последние пользователи</h2>@foreach($users as $user)<div class="line"><span>{{ $user->nickname }} <span class="small">· {{ $user->email }}</span></span><span class="small">{{ $user->role }}</span></div>@endforeach</section>
<section class="panel"><h2>Последние турниры</h2>@foreach($tournaments as $tournament)<div class="line"><span>{{ $tournament->title }} <span class="small">· {{ $tournament->game->short_name }}</span></span><span class="small">{{ $tournament->status }}</span></div>@endforeach</section>
</main></div></body></html>
